<template>
  <v-container fluid grid-list-lg class="site-page site-page--wide site-stack solutions-page">
    <SitePageHeader :summary="model.solutions.summary"
                    :title="model.solutions.title"
                    class="solutions-page__header">
      <template v-slot:actions>
        <v-btn :to="{path: constants.contactPath}"
               class="site-action site-action--secondary"
               color="primary"
               outline>
          <v-icon left>mail</v-icon>
          {{ titles.contactPage }}
        </v-btn>
      </template>
    </SitePageHeader>

    <v-layout row wrap>
      <v-flex :key="solution.route" md6 xs12 v-for="solution in solutions">
        <SolutionCard :solution="solution"/>
      </v-flex>
    </v-layout>

    <v-card class="site-card" flat>
      <v-card-text class="site-card__body site-lead">{{ model.solutions.contactPrompt }}</v-card-text>
      <v-card-actions class="site-card__footer">
        <v-btn :to="{path: constants.contactPath}"
               class="site-action site-action--primary"
               color="primary">
          <v-icon left>mail</v-icon>
          {{ titles.homeContactAction }}
        </v-btn>
      </v-card-actions>
    </v-card>

  </v-container>
</template>

<style lang="stylus" scoped>
.solutions-page__header >>> .site-page-header__content
  max-width 1050px
</style>

<script lang="ts">
import {Component} from 'vue-property-decorator'
import PortalPageBase from '@/view/PortalPageBase'
import SolutionCard from '@/view/Solutions/SolutionCard.vue'
import SitePageHeader from '@/view/SitePageHeader.vue'
import {breadcrumbList, canonicalUrl, pageMetaInfo, socialCardPath} from '@/model/Seo'
import {brandName} from '@/model/Brand'

@Component({components: {SitePageHeader, SolutionCard}})
export default class Solutions extends PortalPageBase {
  pageTitle = this.titles.solutionsPage

  get solutions() {
    return Array.from(this.model.solutions.values())
  }

  metaInfo(): any {
    const structuredData = {
      '@context': 'https://schema.org',
      '@graph': [
        {
          '@type': 'CollectionPage',
          name: this.titles.solutionsPage,
          description: this.titles.solutionsDescription,
          url: canonicalUrl(this.constants.solutionsPath),
          mainEntity: {
            '@type': 'ItemList',
            itemListElement: this.solutions.map((solution, index) => ({
              '@type': 'ListItem',
              position: index + 1,
              name: solution.title,
              description: solution.summary
            }))
          }
        },
        breadcrumbList([
          {name: brandName, path: '/'},
          {name: this.titles.homePage, path: this.constants.introductionPath},
          {name: this.titles.solutionsPage, path: this.constants.solutionsPath}
        ])
      ]
    }
    return pageMetaInfo(
      this.titles.solutionsSeoTitle,
      this.titles.solutionsDescription,
      this.constants.solutionsPath,
      socialCardPath(this.constants.solutionsPath),
      structuredData
    )
  }

  beforeRouteEnter(to: any, from: any, next: any) {
    super.beforeRouteEnter(to, from, next)
  }
}
</script>
